import hashlib, heapq, math

class TopK:
    """Approximate heavy hitters: a count-min sketch for counts, K candidates beside it."""
    def __init__(self, k: int, eps: float = 1e-5, delta: float = 0.01):
        self.k = k
        self.w = math.ceil(math.e / eps)          # overcount <= eps * N ...
        self.d = math.ceil(math.log(1 / delta))   # ... with probability 1 - delta
        self.rows = [[0] * self.w for _ in range(self.d)]
        self.top: dict[str, int] = {}             # the answer: candidate -> estimate

    def _cells(self, item: str):
        h = hashlib.blake2b(item.encode(), digest_size=16).digest()
        h1, h2 = int.from_bytes(h[:8], "big"), int.from_bytes(h[8:], "big") | 1
        return [(r, (h1 + r * h2) % self.w) for r in range(self.d)]

    def estimate(self, item: str) -> int:
        return min(self.rows[r][c] for r, c in self._cells(item))   # never undercounts

    def add(self, item: str, n: int = 1) -> None:
        for r, c in self._cells(item):
            self.rows[r][c] += n
        self.top[item] = self.estimate(item)
        if len(self.top) > self.k:                # evict the weakest candidate
            del self.top[min(self.top, key=self.top.get)]   # a min-heap in production

    def merge(self, other: "TopK") -> None:       # same w, d and hash functions
        for mine, theirs in zip(self.rows, other.rows):
            for i, v in enumerate(theirs):
                mine[i] += v                      # sketches add cell by cell
        cands = set(self.top) | set(other.top)    # re-score both candidate lists
        best = heapq.nlargest(self.k, cands, key=self.estimate)
        self.top = {x: self.estimate(x) for x in best}
